WITH enriched AS (SELECT *, MAX(quantity) OVER w_recent AS running_max_quantity, SUM(quantity) OVER w_recent AS running_sum_quantity, MIN(quantity) OVER w_recent AS running_min_quantity, AVG(quantity) OVER w_recent AS running_avg_quantity FROM order_items WINDOW w_recent AS (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN running_min_quantity >= 8.9 THEN 'HIGH' ELSE 'LOW' END AS running_min_quantity_tier, CASE WHEN quantity >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, CASE WHEN running_sum_quantity >= 40 THEN 'HIGH' ELSE 'LOW' END AS running_sum_quantity_tier, ROUND(AVG(running_min_quantity), 2) AS avg_running_min_quantity, PERCENTILE_APPROX(running_min_quantity, ARRAY(0.25, 0.5, 0.75)) AS running_min_quantity_quartiles, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_level FROM enriched GROUP BY GROUPING SETS ((CASE WHEN running_min_quantity >= 8.9 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN quantity >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN running_sum_quantity >= 40 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN running_min_quantity >= 8.9 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN quantity >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END), ())
